mapper.select:
SELECT id, user_id, view_scale, outdoor_mode_yn, reduce_motion_yn, last_selected_farm_id, created_at, updated_at
FROM user_preference
WHERE user_id = #{userId}

mapper.update:
UPDATE user_preference
SET view_scale = #{viewScale},
    outdoor_mode_yn = #{outdoorModeYn},
    reduce_motion_yn = #{reduceMotionYn},
    updated_at = #{updatedAt}
WHERE user_id = #{userId}
